NUL = 1000

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def countDownwardPaths(tree, target):
    vals, left, right = _links(tree)
    n = len(vals)
    if n == 0:
        return 0
    cnt = {0: 1}
    ans = 0
    stack = [(0, 0, 0)]  # (node, prefix sum of its parent, phase: 0 = enter, 1 = exit)
    while stack:
        k, sp, phase = stack.pop()
        if phase == 1:
            cnt[sp] -= 1  # here sp holds the node's own prefix sum
            continue
        s = sp + vals[k]
        ans += cnt.get(s - target, 0)
        cnt[s] = cnt.get(s, 0) + 1
        stack.append((k, s, 1))
        if right[k] != -1:
            stack.append((right[k], s, 0))
        if left[k] != -1:
            stack.append((left[k], s, 0))
    return ans
